/*
 * Client Workspace Demo Overlay theme overlay.
 * Generated from @create-something/canon/overlays/project-template.
 * Keep aliases pointed at Canon tokens instead of forking primitives.
 */

:root {
	--overlay-accent: var(--color-performance-signal, #0057b8);
	--overlay-accent-contrast: var(--color-performance-panel, #ffffff);
	--overlay-surface: var(--color-performance-panel, #ffffff);
	--overlay-surface-muted: var(--color-performance-paper, #f3f3f0);
	--overlay-border: var(--color-performance-line, #d7d7d2);
	--overlay-proof: var(--color-performance-growth, #007a4d);
	--overlay-review: var(--color-performance-gold, #8b6b00);
	--overlay-block: var(--color-performance-risk, #c62026);
	--overlay-radius: var(--radius-performance-md, 4px);
	--overlay-focus-ring: 0 0 0 3px color-mix(in srgb, var(--overlay-accent) 24%, transparent);
}

[data-canon-overlay='overlay.client-workspace-demo'] {
	color: var(--color-performance-ink, #090909);
	background: var(--overlay-surface);
}

[data-canon-overlay='overlay.client-workspace-demo'] :focus-visible {
	outline: none;
	box-shadow: var(--overlay-focus-ring);
}

files.canon-overlay/tokens.json:
{
  "$schema": "https://design-tokens.github.io/community-group/format/",
  "$extensions": {
    "canonOverlay": {
      "id": "overlay.client-workspace-demo",
      "name": "Client Workspace Demo Overlay",
      "sourcePackage": "@create-something/client-workspace-demo"
    }
  },
  "canonOverlay": {
    "accent": {
      "$type": "color",
      "$value": "{color.performance.signal}",
      "$description": "Project accent alias. Keep the underlying Canon token as the source of truth."
    },
    "surface": {
      "$type": "color",
      "$value": "{color.performance.panel}",
      "$description": "Default overlay surface alias for web and app shells."
    },
    "proof": {
      "$type": "color",
      "$value": "{color.performance.ready}",
      "$description": "Evidence and receipt state alias. Must be paired with text labels."
    },
    "radius": {
      "$type": "dimension",
      "$value": "{radius.performance.md}",
      "$description": "Overlay radius alias. Do not introduce a project-specific radius scale."
    }
  }
}

